import { walletFundingSummary } from '../../shared/fundingProvenance.ts';
import { createClientFromRequest } from 'npm:@base44/sdk@0.8.38';
import { postLedgerLegs } from '../../shared/ledger.ts';
import { recordIntegrationEvent } from '../../shared/integrationEvents.ts';
import { seamlessWithdrawalsEnabled } from '../../shared/seamlessFundingConfig.ts';
import { extendComplianceEvidenceRetention } from '../../shared/complianceEvidence.ts';
import { hasVerifiedIdentity } from '../../shared/identityEligibility.js';
import { legalNameFromUser } from '../../shared/legalName.ts';
import {
  seamlessConfig, seamlessRequest, buildWithdrawalBody,
  PATH_CHECK_SEND, SEAMLESS_PROVIDER_KEY,
} from '../../shared/seamlessAch.ts';
import { acquireUserWalletLock, releaseUserWalletLock } from '../../shared/seamlessAtomicStore.ts';

import { sendLimitedWithdrawal } from '../../shared/limitedWithdrawal.ts';
import { MAX_WITHDRAWAL_AMOUNT } from '../../shared/withdrawalLimits.js';

// Self-service account closure. Runs server-side with the service role so
// contest cancellations, refunds, and the closure payout are always computed
// via the Internal Ledger — never trusted from the client.

Deno.serve(async (req) => {
  let lockOwner = '';
  let lockedUserId = '';
  try {
    const base44 = createClientFromRequest(req);
    const user = await base44.auth.me();
    if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 });

    if (user.account_state === 'closed') {
      return Response.json({ error: 'This account is already closed' }, { status: 400 });
    }

    // A closure payout is a withdrawal. Serialize against any concurrent
    // submitSeamlessWithdrawal (or a second, double-clicked closure request)
    // touching the same wallet, using the same lock those requests take.
    lockOwner = crypto.randomUUID();
    lockedUserId = user.id;
    if (!await acquireUserWalletLock(user.id, lockOwner)) {
      return Response.json({ error: 'withdrawal_in_progress', retryable: true }, { status: 409 });
    }

    // Keep account access intact when the remaining balance needs multiple transfers.
    const closureWallet = (await base44.asServiceRole.entities.Wallet.filter({ user_id: user.id }))[0];
    if (Number(closureWallet?.available_balance || 0) > MAX_WITHDRAWAL_AMOUNT) {
      return Response.json({ error: 'Your balance requires more than one bank transfer. Withdraw up to $1,100 at a time from your wallet, then return here to close your account. Your account remains open.', action: 'withdraw_balance_first' }, { status: 409 });
    }

    // (i) Cancel any open Contest invitations — hosted/accepted contests that
    // have not yet fully started (searching, matched, or one-sided deposit),
    // refunding any escrowed deposit already made. Contests already
    // "in_progress" are left to settle normally per (iii).
    const [asHost, asOpponent] = await Promise.all([
      base44.asServiceRole.entities.Match.filter({ player1_id: user.id }),
      base44.asServiceRole.entities.Match.filter({ player2_id: user.id }),
    ]);
    const openInvitations = [...asHost, ...asOpponent].filter((m) =>
      ['searching', 'matched', 'deposited'].includes(m.status)
    );

    for (const match of openInvitations) {
      const refundTargets = [];
      if (match.player1_deposited) refundTargets.push(match.player1_id);
      if (match.player2_deposited) refundTargets.push(match.player2_id);

      for (const depositorId of refundTargets) {
        const walletTransaction = await base44.asServiceRole.entities.WalletTransaction.create({
          launch_epoch: 2,
          user_id: depositorId,
          type: 'wager_refund',
          amount: match.wager_amount,
          match_id: match.id,
          description: 'Reserved contest funds refunded — account closure',
          status: 'completed',
        });

        await postLedgerLegs(base44, {
          groupId: `match:${match.id}:account_closure_match_cancelled:${walletTransaction.id}`,
          matchId: match.id,
          walletTransactionId: walletTransaction.id,
          actor: 'user',
          actorId: user.id,
          triggerEvent: 'account_closure_match_cancelled',
          externalRefType: 'match',
          externalRefId: match.id,
          legs: [
            { ledgerAccount: 'contest_clearing', debit: match.wager_amount, credit: 0, transactionType: 'refund' },
            { ledgerAccount: 'user_account', userId: depositorId, debit: 0, credit: match.wager_amount, heldDelta: -match.wager_amount, transactionType: 'refund', totalWageredDelta: -match.wager_amount },
          ],
        });
      }

      await base44.asServiceRole.entities.Match.update(match.id, { status: 'cancelled' });
      await recordIntegrationEvent(base44, {
        eventType: 'contest.cancelled',
        aggregateType: 'match',
        aggregateId: match.id,
        correlationId: match.id,
        idempotencyKey: `contest.cancelled:${match.id}`,
        actorType: 'user',
        actorId: user.id,
        userId: user.id,
        counterpartyUserId: match.player1_id === user.id ? match.player2_id : match.player1_id,
        matchId: match.id,
        status: 'cancelled',
        amount: match.wager_amount,
        result: 'account_closure',
        eventData: {
          refunded_user_ids: refundTargets,
        },
      });
    }

    // (iv) Disburse any remaining undisputed balance, subject to compliance
    // holds. A withdrawal_hold means the balance stays put pending review.
    //
    // This must actually reach the user's bank, not just move the ledger.
    // A prior version of this function debited Available Balance and
    // credited a generic 'settlement' account, leaving the WalletTransaction
    // 'pending'/'unrouted' with no code path that ever submitted it to
    // Seamless — real closure payouts got permanently stuck. This now
    // reuses the same reservation ledger accounts, IntegrationReference
    // shape, and check-send call as submitSeamlessWithdrawal, so a closure
    // payout is picked up by the exact same webhook and
    // reconcile-seamless-ach-statuses recovery machinery as any other
    // withdrawal — never a separate, unrouted path.
    let payout = null;
    let payoutStatus = null;
    if (!user.withdrawal_hold) {
      const wallets = await base44.asServiceRole.entities.Wallet.filter({ user_id: user.id });
      const wallet = wallets[0];
      if (wallet && wallet.available_balance > 0) {
        const funding = await walletFundingSummary(base44, user.id);
        if (funding.withdrawal_restricted_balance > 0) {
          return Response.json({ error: 'Some funds are available to play but remain under a bank withdrawal hold. Wait for the withdrawal review before closing your account, or contact support.', action: 'ach_withdrawal_hold', next_withdrawal_review_at: funding.next_withdrawal_review_at }, { status: 409 });
        }
        payout = funding.available_to_withdraw;
        if (payout > MAX_WITHDRAWAL_AMOUNT) {
          return Response.json({ error: 'After returning reserved contest funds, your balance exceeds the $1,100 bank transfer limit. Withdraw funds from your wallet before closing your account.', action: 'withdraw_balance_first', available_balance: payout }, { status: 409 });
        }

        if (!seamlessWithdrawalsEnabled()) {
          return Response.json({
            error: 'Payouts are not available yet, so an account with a remaining balance cannot be closed right now. Please try again later.',
            action: 'withdrawals_unavailable',
            available_balance: payout,
          }, { status: 409 });
        }
        if (!await hasVerifiedIdentity(base44, user)) {
          return Response.json({
            error: 'Verify your identity (21+) before a self-service closure payout. Contact hello@worldchessbet.com for help returning existing funds.',
            action: 'identity_verification_required',
            available_balance: payout,
          }, { status: 400 });
        }
        const banks = await base44.asServiceRole.entities.SeamlessBankAccount.filter({ user_id: user.id, status: 'verified' });
        const bank = banks.find((item) => item.source_id && item.is_primary) || banks[0];
        if (!bank?.source_id) {
          return Response.json({
            error: 'Link and verify a bank account before closing an account with a remaining balance — there is no way to send your remaining balance without one.',
            action: 'bank_link_required',
            available_balance: payout,
          }, { status: 400 });
        }
        const profile = (await base44.asServiceRole.entities.SeamlessPaymentProfile.filter({ user_id: user.id }))[0];
        if (!profile?.provider_user_id) {
          return Response.json({ error: 'No Seamless customer profile', action: 'ensure_customer', available_balance: payout }, { status: 400 });
        }
        let complianceEvidence;
        try {
          complianceEvidence = await extendComplianceEvidenceRetention(base44, { userId: user.id, fundingSourceId: bank.source_id, requireAchAuthorization: false });
        } catch {
          return Response.json({
            error: 'Required retained verified-bank evidence is unavailable.',
            action: 'compliance_evidence_required',
            available_balance: payout,
          }, { status: 409 });
        }
        const accountHolderName = legalNameFromUser(user);
        if (!accountHolderName) {
          return Response.json({
            error: 'A verified account holder name is required before closing an account with a remaining balance.',
            available_balance: payout,
          }, { status: 400 });
        }
        seamlessConfig(); // fail closed before any provider mutation

        const walletTransaction = await base44.asServiceRole.entities.WalletTransaction.create({
          launch_epoch: 2,
          user_id: user.id,
          type: 'withdrawal',
          amount: payout,
          description: 'Account closure disbursement',
          status: 'pending',
          integration_status: 'pending',
          currency: 'USD',
          direction: 'reserve',
          source_event: 'account_closure_withdrawal_request',
          initiating_actor: 'user',
          initiating_actor_id: user.id,
          correlation_id: '',
          schema_version: 1,
          // Same rationale as submitSeamlessWithdrawal: capture the specific
          // bank account used now, not re-derived later from the user's
          // (possibly since-changed) primary bank account.
          funding_source_id: bank.source_id,
          ach_authorization_id: complianceEvidence?.authorization_id || '',
        });

        // Reserve funds using the same ledger accounts/group-id convention as
        // a normal withdrawal (not the old direct debit-to-'settlement'
        // pattern), so this transaction is indistinguishable from a
        // self-service withdrawal to every downstream consumer (webhook,
        // reconciliation sweep, admin tooling).
        const reservationGroupId = `seamless:withdrawal:reserve:${walletTransaction.id}`;
        await postLedgerLegs(base44, {
          groupId: reservationGroupId,
          walletTransactionId: walletTransaction.id,
          actor: 'user',
          actorId: user.id,
          triggerEvent: 'withdrawal_reservation',
          externalRefType: 'provider_payout',
          externalRefId: walletTransaction.id,
          legs: [
            { ledgerAccount: 'user_account', userId: user.id, debit: payout, credit: 0, heldDelta: payout, transactionType: 'withdrawal' },
            { ledgerAccount: 'withdrawal_reserve', debit: 0, credit: payout, transactionType: 'withdrawal' },
          ],
        });
        await base44.asServiceRole.entities.WalletTransaction.update(walletTransaction.id, {
          integration_status: 'reserved', source_event: 'account_closure_withdrawal_reservation',
        });

        const label = `chessbet-closure-${walletTransaction.id}`;
        await base44.asServiceRole.entities.IntegrationReference.create({
          provider_key: SEAMLESS_PROVIDER_KEY, reference_type: 'payout', external_reference_id: label,
          internal_entity_type: 'wallet_transaction', internal_entity_id: walletTransaction.id, correlation_id: walletTransaction.id,
          idempotency_key: `account-closure:${walletTransaction.id}`, user_id: user.id, wallet_transaction_id: walletTransaction.id,
          status: 'submitting', effective_at: new Date().toISOString(),
          metadata_json: JSON.stringify({ provider: SEAMLESS_PROVIDER_KEY, direction: 'withdrawal', label, source_id: bank.source_id, transfer_speed: 'standard' }),
        });
        await base44.asServiceRole.entities.WalletTransaction.update(walletTransaction.id, {
          integration_status: 'submitting', source_event: 'account_closure_withdrawal_submitting',
        });

        let data;
        try {
          data = await sendLimitedWithdrawal(base44, walletTransaction.id, buildWithdrawalBody({
            providerUserId: profile.provider_user_id, name: accountHolderName.fullName, amount: payout,
            description: 'Account closure disbursement', label, sourceId: bank.source_id,
          }));
        } catch (error) {
          const status = Number(error?.status || 0);
          if (status >= 400 && status < 500) {
            // Provider rejected outright — release the reservation back to
            // available balance rather than stranding it, and stop the closure
            // so the user can resolve the rejection (e.g. re-link their bank)
            // with their account still open.
            const releaseGroupId = `seamless:withdrawal:release:${walletTransaction.id}`;
            await postLedgerLegs(base44, {
              groupId: releaseGroupId,
              walletTransactionId: walletTransaction.id,
              actor: 'system',
              triggerEvent: 'withdrawal_reservation_release',
              externalRefType: 'provider_payout',
              externalRefId: walletTransaction.id,
              legs: [
                { ledgerAccount: 'withdrawal_reserve', debit: payout, credit: 0, transactionType: 'reversal' },
                { ledgerAccount: 'user_account', userId: user.id, debit: 0, credit: payout, heldDelta: -payout, transactionType: 'reversal' },
              ],
            });
            await base44.asServiceRole.entities.WalletTransaction.update(walletTransaction.id, {
              status: 'failed', integration_status: 'failed', source_event: 'account_closure_withdrawal_rejected',
              description: `Account closure disbursement rejected by Seamless: ${String(error?.message || '').slice(0, 200)}`,
              processed_at: new Date().toISOString(),
            });
            return Response.json({
              error: error.payoutCapacity ? 'Bank transfer capacity is currently full. Your balance is available in your wallet and your account remains open. Please try closing your account later.' : 'Unable to submit your closure payout to your bank. Your balance was returned to your wallet — please try again, or contact support.',
              available_balance: payout,
            }, { status: 502 });
          }
          // Ambiguous network/provider outcome: never retry blindly and never
          // release the reservation — the existing Seamless status-recovery
          // sweep (reconcile-seamless-ach-statuses) resolves this exactly like
          // any other uncertain withdrawal once the true outcome is knowable.
          await base44.asServiceRole.entities.WalletTransaction.update(walletTransaction.id, {
            integration_status: 'uncertain', source_event: 'account_closure_withdrawal_uncertain',
          });
          payoutStatus = 'uncertain';
          data = null;
        }

        if (data) {
          const providerRef = data?.check_id || data?.check?.id || data?.id || data?.check?.check_id || '';
          if (providerRef) {
            await base44.asServiceRole.entities.IntegrationReference.create({
              provider_key: SEAMLESS_PROVIDER_KEY, reference_type: 'payout', external_reference_id: providerRef,
              internal_entity_type: 'wallet_transaction', internal_entity_id: walletTransaction.id, correlation_id: walletTransaction.id,
              idempotency_key: `account-closure:${walletTransaction.id}:ref`, user_id: user.id, wallet_transaction_id: walletTransaction.id,
              status: 'submitted', effective_at: new Date().toISOString(),
              metadata_json: JSON.stringify({ provider: SEAMLESS_PROVIDER_KEY, direction: 'withdrawal', label, source_id: bank.source_id, transfer_speed: 'standard' }),
            });
            await base44.asServiceRole.entities.WalletTransaction.update(walletTransaction.id, {
              integration_status: 'submitted', source_event: 'account_closure_withdrawal_submitted',
            });
            payoutStatus = 'submitted';
          } else {
            await base44.asServiceRole.entities.WalletTransaction.update(walletTransaction.id, {
              integration_status: 'uncertain', source_event: 'account_closure_withdrawal_uncertain',
            });
            payoutStatus = 'uncertain';
          }
        }

        await recordIntegrationEvent(base44, {
          eventType: 'financial.seamless_withdrawal_submitted', aggregateType: 'wallet_transaction', aggregateId: walletTransaction.id,
          correlationId: walletTransaction.id, idempotencyKey: `seamless:withdrawal:submitted:${walletTransaction.id}`,
          actorType: 'user', actorId: user.id, userId: user.id, walletTransactionId: walletTransaction.id,
          status: payoutStatus || 'pending', amount: payout, result: payoutStatus || 'pending',
          eventData: { provider: SEAMLESS_PROVIDER_KEY, label, reason: 'account_closure' },
        });
      }
    }

    // (v) Transition the Account to Closed status — this also blocks new
    // deposits, withdrawals, and contest entry per the existing account_state gate.
    const updatedUser = await base44.asServiceRole.entities.User.update(user.id, {
      account_state: 'closed',
    });

    await recordIntegrationEvent(base44, {
      eventType: 'account.closed',
      aggregateType: 'user',
      aggregateId: user.id,
      correlationId: user.id,
      idempotencyKey: `account.closed:${user.id}`,
      actorType: 'user',
      actorId: user.id,
      userId: user.id,
      status: updatedUser.account_state,
      amount: payout || 0,
      result: user.withdrawal_hold ? 'funds_held_for_compliance' : 'closure_requested',
      eventData: {
        cancelled_match_ids: openInvitations.map((match) => match.id),
        payout_pending: payout,
        withdrawal_hold: !!user.withdrawal_hold,
      },
    });

    return Response.json({
      success: true,
      cancelled_invitations: openInvitations.length,
      payout_pending: payout,
      payout_status: payoutStatus,
      held_for_compliance: !!user.withdrawal_hold,
      user: updatedUser,
    });
  } catch (error) {
    console.error(JSON.stringify({ event: 'backend_function_failed', error: error?.message || 'unknown_error' }));
    return Response.json({ error: 'internal_error' }, { status: 500 });
  } finally {
    if (lockedUserId && lockOwner) {
      try { await releaseUserWalletLock(lockedUserId, lockOwner); } catch { /* TTL safely releases an unavailable store lock. */ }
    }
  }
});

src/components/wallet/SeamlessFundingPan:
import { Link } from "react-router-dom";
import React, { useState, useEffect, useCallback, useRef } from "react";
import {
  Plus, Loader2, CheckCircle2, Clock, AlertTriangle,
  XCircle, Link2, Trash2, Check, ChevronUp,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { base44 } from "@/api/base44Client";
import DepositLocationStep from "./DepositLocationStep";
import { walletJourneyCopy } from "@/lib/walletJourneyCopy";
import SeamlessPlaidBankLink from "./SeamlessPlaidBankLink";
import SocureIdentityStep from "./SocureIdentityStep";
import WalletSetupStep from "./WalletSetupStep";
import { depositQuote } from "../../../base44/shared/depositPricing.js";

// Seamless ACH funding panel. Bank credentials are collected only inside the
// Seamless-hosted Plaid flow. Verification, deposits, and withdrawals remain
// independently controlled by server-side state and provider webhooks.

const BANK_STATUS = {
  verified: { label: "Connected", color: "text-emerald-400", icon: CheckCircle2 },
  pending_verification: { label: "Awaiting verification", color: "text-amber-400", icon: Clock },
  added: { label: "Awaiting verification", color: "text-amber-400", icon: Clock },
  verification_failed: { label: "Needs attention", color: "text-red-400", icon: XCircle },
  verification_expired: { label: "Reconnect required", color: "text-red-400", icon: XCircle },
  deleted: { label: "Removed", color: "text-white/40", icon: XCircle },
  error: { label: "Needs attention", color: "text-red-400", icon: XCircle },
};

function BankRow({ bank, busy, onMakePrimary, onDisconnect }) {
  const s = BANK_STATUS[bank.status] || BANK_STATUS.added;
  const Icon = s.icon;
  const isVerified = bank.status === "verified";
  const canDisconnect = bank.status !== "deleted";
  return (
    <div className="rounded-xl bg-white/[0.03] border border-white/5 px-4 py-3">
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-3 min-w-0">
          <div className="h-9 w-9 rounded-lg bg-white/[0.04] flex items-center justify-center shrink-0">
            <Link2 size={16} className="text-white/50" />
          </div>
          <div className="min-w-0">
            <p className="text-sm text-white/90 truncate">
              {bank.account_name || "Bank account"}
              {bank.account_mask ? ` ending in ${bank.account_mask}` : ""}
            </p>
            {bank.is_primary && (
              <span className="text-[10px] uppercase tracking-wider text-[#C9A84C]">
                {isVerified ? "Primary" : "Selected · awaiting verification"}
              </span>
            )}
          </div>
        </div>
        <span className={`flex items-center gap-1.5 text-xs font-medium ${s.color} shrink-0`}>
          <Icon size={14} /> {s.label}
        </span>
      </div>
      {canDisconnect && (
        <div className="mt-3 flex justify-end gap-2 border-t border-white/5 pt-3">
          {isVerified && !bank.is_primary && (
            <button
              type="button"
              onClick={() => onMakePrimary(bank)}
              disabled={!!busy}
              className="flex items-center gap-1.5 rounded-lg border border-white/10 px-3 py-1.5 text-xs text-white/65 hover:border-[#C9A84C]/40 hover:text-[#C9A84C] disabled:opacity-40"
            >
              {busy === `primary:${bank.id}` ? <Loader2 size={13} className="animate-spin" /> : <Check size={13} />}
              Use this bank
            </button>
          )}
          <button
            type="button"
            onClick={() => onDisconnect(bank)}
            disabled={!!busy}
            className="flex items-center gap-1.5 rounded-lg border border-red-500/20 px-3 py-1.5 text-xs text-red-300/75 hover:border-red-400/40 hover:text-red-300 disabled:opacity-40"
          >
            {busy === `disconnect:${bank.id}` ? <Loader2 size={13} className="animate-spin" /> : <Trash2 size={13} />}
            Disconnect
          </button>
        </div>
      )}
    </div>
  );
}

export default function SeamlessFundingPanel({
  wallet,
  pendingDeposits = 0,
  accountState,
  withdrawalHold,
  onRefresh,
  onFundingState,
}) {
  const [state, setState] = useState(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(false);
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [locationOverride, setLocationOverride] = useState(null);
  const [amount, setAmount] = useState("");
  const [direction, setDirection] = useState("deposit");
  const [showBankManager, setShowBankManager] = useState(false);
  const [showBankLink, setShowBankLink] = useState(false);
  const [bankToDisconnect, setBankToDisconnect] = useState(null);
  const depositRequestKey = useRef("");
  const withdrawalRequestKey = useRef("");
  const pollAttempts = useRef(0);
  const load = useCallback(async () => {
    try {
      let syncUnavailable = false;
      try { await base44.functions.invoke("refreshSocureIdentityVerification", {}); }
      catch { syncUnavailable = true; }
      const { data } = await base44.functions.invoke("getSeamlessWalletState", {});
      if (data?.identity) data.identity.sync_unavailable = syncUnavailable;
      setState(data);
      if (onFundingState) onFundingState(data?.funding || null);
      setLoadError(false);
      return data;
    } catch {
      setLoadError(true);
    } finally {
      setLoading(false);
    }
  }, [onFundingState]);

  useEffect(() => { load(); }, [load]);

  // Keep the open wallet current while a bank transfer is processing or a
  // processed deposit is in its clearing window. The backend remains the
  // authoritative 15-minute monitor even when this page is closed.
  useEffect(() => {
    const hasPending = loadError ||
      ["pending", "incomplete", "review_required"].includes(state?.identity?.status) ||
      state?.banks?.some((b) => ["added", "pending_verification"].includes(b.status)) ||
      state?.recent?.some((t) => t.status === "pending" || t.deposit_hold_status === "held" || t.deposit_withdrawal_status === "held");
    if (!hasPending) {
      pollAttempts.current = 0;
      return;
    }
    if (pollAttempts.current >= 120) return;
    const timer = setTimeout(async () => {
      pollAttempts.current += 1;
      const before = JSON.stringify(state?.recent || []);
      const next = await load();
      const after = JSON.stringify(next?.recent || []);
      if ((before !== after || state?.identity?.status !== next?.identity?.status) && onRefresh) await onRefresh();
    }, state?.identity?.status === "pending" && pollAttempts.current < 24 ? 5000 : 30000);
    return () => clearTimeout(timer);
  }, [state, loadError, load, onRefresh]);

  const submit = async () => {
    const v = parseFloat(amount);
    if (!v || v <= 0 || !wallet) return;
    if (busy) return;
    setError(""); setNotice(""); setBusy(direction);
    try {
      const fn = direction === "deposit" ? "submitSeamlessDeposit" : "submitSeamlessWithdrawal";
      const payload = { amount: v, ...(direction === "deposit" ? {bankSourceId:providerPrimaryBank?.source_id, depositPricingVersion:quote?.version, authorizedBankDebit:quote?.bankDebit} : {}) };
      const requestKey = direction === "deposit" ? depositRequestKey : withdrawalRequestKey;
      requestKey.current ||= crypto.randomUUID();
      payload.idempotencyKey = requestKey.current;
      const { data } = await base44.functions.invoke(fn, payload);
      if (!data?.enabled) throw new Error(data?.reason || "Bank transfers are unavailable right now.");
      // Preserve the key for an in-doubt provider result: pressing submit again
      // asks the server for the same logical transfer, never a second ACH request.
      if (data?.status !== "uncertain") requestKey.current = "";
      if (data?.status !== "uncertain") setAmount("");
      setNotice(data?.status === "uncertain" ? "Your bank has not confirmed this request yet. Do not submit another transfer; check Transaction History for updates." : direction === "deposit" ? "Deposit requested. Funds become available after processing and clearing. Follow its progress in Transaction History." : "Withdrawal requested. Follow its progress in Transaction History.");
      await load();
      if (onRefresh) onRefresh();
    } catch (e) {
      if (e?.response?.data?.action === "location_required") setLocationOverride({allowed:false,reason:e.response.data.error});
      if (e?.response?.data?.request_terminal === true) {
        (direction === "deposit" ? depositRequestKey : withdrawalRequestKey).current = "";
      }
      const serverMessage = e?.response?.data?.error;
      const message = typeof serverMessage === "string" && serverMessage
        ? serverMessage
        : "We couldn't submit that request. Please try again or contact support.";
      // Reload the durable transaction so an immediate provider decline appears
      // in both the compact transfer list and full Transaction History.
      try {
        await load();
        if (onRefresh) await onRefresh();
      } catch { /* Preserve the original transfer error below. */ }
      setError(message);
    } finally {
      setBusy("");
    }
  };

  const manageBank = async (action, bank) => {
    const busyKey = action === "set_primary" ? `primary:${bank.id}` : `disconnect:${bank.id}`;
    setBusy(busyKey);
    setError("");
    try {
      await base44.functions.invoke("manageSeamlessBankAccount", {
        action,
        bankId: bank.id,
      });
      setBankToDisconnect(null);
      await load();
      if (onRefresh) onRefresh();
    } catch (e) {
      const serverMessage = e?.response?.data?.error;
      setError(typeof serverMessage === "string" && serverMessage
        ? serverMessage
        : "We couldn't update that bank account. Please try again.");
    } finally {
      setBusy("");
    }
  };

  const MIN_DEPOSIT_AMOUNT = 10;
  const SMALL_WITHDRAWAL_THRESHOLD = 10;
  const SMALL_WITHDRAWAL_FEE = 2.5;
  const parsedAmount = parseFloat(amount);
  const quote = depositQuote(parsedAmount);
  // Mirrors the server's full-balance fee waiver (submitSeamlessWithdrawal):
  // withdrawing the entire available balance skips the small-withdrawal fee,
  // so a balance under $10 (or even under the fee itself) is never stranded.
  const isFullBalanceWithdrawal =
    !!wallet && parsedAmount > 0 && parsedAmount >= (state?.funding?.available_to_withdraw || 0) - 0.005;

  const journey = walletJourneyCopy({wallet: wallet || {}, funding: state || {}, pendingDeposits});
  const location = state?.onboarding_location?.allowed ? state.onboarding_location : locationOverride || state?.onboarding_location;
  const locationApproved = location?.allowed === true;
  const depositsEnabled = !!state?.deposits_enabled && locationApproved;
  const withdrawalsEnabled = !!state?.withdrawals_enabled;
  const hostedPlaidEnabled = !!state?.hosted_plaid_enabled;
  const accountVerified = !!state?.account_verified;
  const effectiveAccountState = state?.account_state || accountState;
  const effectiveWithdrawalHold = state?.withdrawal_hold ?? withdrawalHold;
  const accountRestricted = ["suspended", "closed"].includes(effectiveAccountState);
  const notVerified = !accountVerified || effectiveAccountState !== "verified";
  const ineligible = effectiveWithdrawalHold || accountRestricted || notVerified;
  const providerPrimaryBank = state?.banks?.find((b) => b.is_primary) || null;
  const verifiedBank =
    state?.banks?.find((b) => b.status === "verified" && b.is_primary) ||
    state?.banks?.find((b) => b.status === "verified");
  const bankPending = state?.banks?.some((b) =>
    ["added", "pending_verification"].includes(b.status)
  );
  const bankNeedsAttention = !verifiedBank && state?.banks?.some(b => ["verification_failed", "verification_expired", "error"].includes(b.status));
  const bankReady = !!verifiedBank;
  const depositSourceReady = providerPrimaryBank?.status === "verified";
  const bankReadyForDirection = direction === "deposit" ? depositSourceReady : bankReady;
  const displayedBank = direction === "deposit" ? (providerPrimaryBank || verifiedBank) : verifiedBank;
  const displayedBankVerified = displayedBank?.status === "verified";
  const transferDirectionEnabled = direction === "deposit" ? depositsEnabled : withdrawalsEnabled;
  const availableBalance = loadError ? 0 : (state?.funding?.available_to_withdraw || 0);
  const meetsMinimum = direction === "deposit" ? parsedAmount >= MIN_DEPOSIT_AMOUNT : parsedAmount > 0;
  const exceedsAvailableBalance = direction === "withdrawal" && parsedAmount > availableBalance + 0.005;
  const exceedsWithdrawalLimit = direction === "withdrawal" && parsedAmount > 1100;
  const canSubmit =
    !ineligible && bankReadyForDirection && !busy && Number.isFinite(parsedAmount) && /^\d+(?:\.\d{1,2})?$/.test(amount) && (direction !== "deposit" || !!quote) && meetsMinimum && !exceedsAvailableBalance && !exceedsWithdrawalLimit && transferDirectionEnabled;
  const transferBusy = busy === direction;
  const formattedAmount = Number.isFinite(parsedAmount) && parsedAmount > 0
    ? parsedAmount.toFixed(2)
    : "";

  if (loading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="animate-spin text-[#C9A84C]" size={22} />
      </div>
    );
  }

  if (loadError) return (
    <div role="alert" className="rounded-3xl border border-amber-500/20 bg-white/[0.03] p-5 space-y-3">
      <h4 className="font-semibold text-white">Unable to refresh your wallet</h4>
      <p className="text-sm text-white/60">We could not confirm your latest bank and identity status. Transfers are paused on this screen until we reconnect. If you just submitted a transfer, check Transaction History once we reconnect before trying again.</p>
      <Link to="/play" className="block font-semibold text-[#E5CA7A]">Play for Free</Link>
      <Button onClick={() => { setLoading(true); load(); }} className="gold-gradient text-black">Retry wallet connection</Button>
      {error && <p className="text-sm text-red-400">{error}</p>}
    </div>
  );

  return (
    <div className="space-y-4">
      <section className="overflow-hidden rounded-3xl border border-white/10 bg-white/[0.03]" aria-label="Wallet setup">
        <div className="flex flex-wrap items-center justify-between gap-2 border-b border-white/10 px-4 py-4 sm:px-5">
          <h2 className="text-base font-semibold text-white">Wallet setup</h2>
          <span className="text-xs text-white/60">{[locationApproved, !!state?.identity?.verified, depositSourceReady].filter(Boolean).length} of 3 complete</span>
        </div>
        <div className="divide-y divide-white/10">
          <p className="mb-3 text-sm text-white/60">You can play free chess while your wallet is being set up or funds are clearing. <Link to="/play" className="font-semibold text-[#E5CA7A]">Play for Free</Link></p>
          <DepositLocationStep decision={location} onDecision={setLocationOverride} />
          <SocureIdentityStep identity={{...state?.identity,can_start:state?.identity?.can_start && locationApproved}} locationApproved={locationApproved} onRefresh={load} />
          <WalletSetupStep number={3} label="Bank connection" title={depositSourceReady ? "Bank Connected" : bankPending ? "Bank verification pending" : bankReady ? "Choose your deposit bank" : bankNeedsAttention ? "Bank connection needs attention" : "Connect your bank"} complete={depositSourceReady} pending={!depositSourceReady && bankPending} attention={bankNeedsAttention && !bankPending}
            description={depositSourceReady ? providerPrimaryBank?.account_name || "Your deposit bank is connected." : bankPending ? "Awaiting bank confirmation. You can play free chess while you wait." : bankReady ? "Select a verified bank in the funding section below." : bankNeedsAttention ? "Review the bank details below and reconnect your account." : !locationApproved || !accountVerified ? "Next, after location and identity verification." : !hostedPlaidEnabled ? "Bank connection is temporarily unavailable." : "Use the secure bank connection form below."} />
        </div>
        {locationApproved && !!state?.identity?.verified && depositSourceReady && <p className="border-t border-white/10 px-4 py-3 text-xs text-white/60 sm:px-5">{!ineligible && depositsEnabled ? "Setup complete. Add money below whenever you’re ready." : "Setup complete. See your account or transfer status below."}</p>}
      </section>

      {/* Provider webhooks are authoritative for account and bank status. */}
      {Number(state?.funding?.withdrawal_restricted_balance) > 0 && (
        <div className="rounded-xl border border-[#C9A84C]/20 bg-[#C9A84C]/5 p-3 text-xs text-white/70">
          ${Number(state.funding.withdrawal_restricted_balance).toFixed(2)} is under a bank withdrawal hold.
          {state.funding.next_withdrawal_review_at && <> Next review: {new Date(state.funding.next_withdrawal_review_at).toLocaleString()}.</>}
          {" "}Deposits can be played after bank confirmation. Withdrawals require five business days from submission and a final bank check. Prizes and refunds may inherit the remaining hold.
        </div>
      )}
      {effectiveWithdrawalHold && (
        <p className="text-xs text-red-400/80 text-center">
          Withdrawals are temporarily on hold while we complete a routine account review.
        </p>
      )}
      {!effectiveWithdrawalHold && notVerified && effectiveAccountState === "provisional" && (
        <p className="text-xs text-white/40 text-center">
          {["pending", "review_required"].includes(state?.identity?.status) ? "Transfers will unlock after your identity is approved." : state?.identity?.status === "rejected" ? "Verification was not approved. Contact support for next steps." : "Complete identity verification to unlock transfers."} Your connected banks stay linked.
        </p>
      )}
      {!effectiveWithdrawalHold && effectiveAccountState === "suspended" && (
        <p className="text-xs text-red-400/80 text-center">
          Your account is currently suspended. Deposits and withdrawals are unavailable.
        </p>
      )}
      {!effectiveWithdrawalHold && effectiveAccountState === "closed" && (
        <p className="text-xs text-red-400/80 text-center">
          This account is closed. Deposits and withdrawals are unavailable.
        </p>
      )}

      {/* Bank connection is a one-time prerequisite. Once verified, funding becomes the focus. */}
      {!bankReady && (
        <div className="rounded-3xl border border-white/5 bg-white/[0.03] p-5 space-y-4">
          <div className="flex items-start gap-3">
            <div>
              <h4 className="text-base font-semibold text-white">Connect your bank</h4>
              <p className="mt-1 text-xs leading-relaxed text-white/45">
                {bankPending
                  ? "Your bank is being verified. This page will update automatically when it is ready."
                  : !hostedPlaidEnabled
                    ? "Secure bank connection is temporarily unavailable."
                    : "Securely link the checking account you want to use. ChessBet never sees or stores your bank login."}
              </p>
            </div>
          </div>

          {state?.banks?.length > 0 && (
            <div className="space-y-2">
              {state.banks.map((bank) => (
                <BankRow
                  key={bank.id}
                  bank={bank}
                  busy={busy}
                  onMakePrimary={(selected) => manageBank("set_primary", selected)}
                  onDisconnect={setBankToDisconnect}
                />
              ))}
            </div>
          )}

          {!bankPending && hostedPlaidEnabled && !accountRestricted && accountVerified && (locationApproved || availableBalance > 0) ? (
            <SeamlessPlaidBankLink
              legalName={state?.legal_name || ""}
              hasWithdrawableBalance={availableBalance > 0}
              disabled={effectiveWithdrawalHold || !accountVerified || (!locationApproved && availableBalance <= 0)}
              onComplete={load}
            />
          ) : !bankPending ? (
            <p className="py-2 text-center text-xs text-white/30">No bank connected yet.</p>
          ) : null}
        </div>
      )}

      {bankReady && (
        <div className="overflow-hidden rounded-3xl border border-white/5 bg-gradient-to-b from-white/[0.045] to-white/[0.02]">
          <div className="space-y-5 p-5">
            <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
              <div>
                <p className="text-[10px] font-semibold uppercase tracking-[0.2em] text-[#C9A84C]">
                  ChessBet wallet
                </p>
                <h4 className="mt-1 text-xl font-bold text-white">
                  {direction === "deposit" ? "Add money" : "Withdraw funds"}
                </h4>
                <p className="mt-1 text-xs leading-relaxed text-white/45">
                  {direction === "deposit"
                    ? journey.anotherDeposit ? "Funds in your ChessBet wallet are used to create or accept match challenges. You can withdraw your funds at any time." : "Choose an amount and add it securely from your connected bank."
                    : "Send available wallet funds back to your connected bank."}
                </p>
              </div>

              <div
                role="group"
                aria-label="Choose a transfer type"
                className="grid grid-cols-2 rounded-xl border border-white/10 bg-black/20 p-1"
              >
                <button
                  type="button"
                  aria-pressed={direction === "deposit"}
                  onClick={() => {
                    setDirection("deposit");
                    setAmount("");
                    setError("");
                  }}
                  disabled={!depositsEnabled || ineligible}
                  className={
                    "rounded-lg px-4 py-2 text-xs font-semibold transition-colors disabled:opacity-30 " +
                    (direction === "deposit"
                      ? "bg-[#C9A84C] text-black"
                      : "text-white/55 hover:text-white")
                  }
                >
                  Add money
                </button>
                <button
                  type="button"
                  aria-pressed={direction === "withdrawal"}
                  onClick={() => {
                    setDirection("withdrawal");
                    setAmount("");
                    setError("");
                  }}
                  disabled={!withdrawalsEnabled || ineligible || availableBalance <= 0}
                  className={
                    "rounded-lg px-4 py-2 text-xs font-semibold transition-colors disabled:opacity-30 " +
                    (direction === "withdrawal"
                      ? "bg-[#C9A84C] text-black"
                      : "text-white/55 hover:text-white")
                  }
                >
                  Withdraw
                </button>
              </div>
            </div>

            <div className="rounded-2xl border border-white/5 bg-black/20 px-4 py-3">
              <div className="flex items-center justify-between gap-3">
                <div className="flex min-w-0 items-center gap-3">
                  <div className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-xl ${displayedBankVerified ? "bg-emerald-500/10" : "bg-amber-500/10"}`}>
                    {displayedBankVerified
                      ? <CheckCircle2 size={17} className="text-emerald-400" />
                      : <Clock size={17} className="text-amber-400" />}
                  </div>
                  <div className="min-w-0">
                    <p className="text-[10px] uppercase tracking-wider text-white/35">
                      {direction === "deposit" ? "From" : "To"}
                    </p>
                    <p className="truncate text-sm font-medium text-white/85">
                      {displayedBank?.account_name || "Connected bank"}
                      {displayedBank?.account_mask ? " ending in " + displayedBank.account_mask : ""}
                    </p>
                    <p className={`text-[10px] ${displayedBankVerified ? "text-emerald-400/75" : "text-amber-300/75"}`}>
                      {displayedBankVerified ? "Connected" : "Awaiting verification"}
                    </p>
                  </div>
                </div>
                <button
                  type="button"
                  aria-expanded={showBankManager}
                  onClick={() => {
                    setShowBankManager((value) => !value);
                    if (showBankManager) setShowBankLink(false);
                  }}
                  disabled={!!busy}
                  className="shrink-0 rounded-lg px-2.5 py-1.5 text-xs font-medium text-[#C9A84C] hover:bg-[#C9A84C]/10 disabled:opacity-40"
                >
                  {showBankManager ? "Done" : "Manage"}
                </button>
              </div>

              {direction === "deposit" && !depositSourceReady && (
                <div className="mt-3 rounded-xl border border-amber-500/20 bg-amber-500/[0.07] p-3">
                  <p className="text-xs leading-relaxed text-amber-100/80">
                    {providerPrimaryBank?.account_name || "Your selected bank"} is still awaiting verification and cannot be used for another deposit yet.
                  </p>
                  {verifiedBank && !verifiedBank.is_primary && (
                    <button
                      type="button"
                      onClick={() => manageBank("set_primary", verifiedBank)}
                      disabled={!!busy}
                      className="mt-2 inline-flex items-center gap-1.5 text-xs font-semibold text-[#E7C866] hover:underline disabled:opacity-40"
                    >
                      {busy === `primary:${verifiedBank.id}` ? <Loader2 size={13} className="animate-spin" /> : <Check size={13} />}
                      Use {verifiedBank.account_name || "connected bank"} for deposits
                    </button>
                  )}
                </div>
              )}

              {showBankManager && (
                <div className="mt-4 space-y-3 border-t border-white/5 pt-4">
                  <div className="space-y-2">
                    {state.banks.map((bank) => (
                      <BankRow
                        key={bank.id}
                        bank={bank}
                        busy={busy}
                        onMakePrimary={(selected) => manageBank("set_primary", selected)}
                        onDisconnect={setBankToDisconnect}
                      />
                    ))}
                  </div>

                  {hostedPlaidEnabled && !accountRestricted && accountVerified && (locationApproved || availableBalance > 0) && (
                    <button
                      type="button"
                      onClick={() => setShowBankLink((value) => !value)}
                      disabled={!!busy || effectiveWithdrawalHold}
                      className="flex w-full items-center justify-center gap-2 rounded-xl border border-white/10 px-3 py-2.5 text-xs font-medium text-white/60 hover:border-[#C9A84C]/40 hover:text-[#C9A84C] disabled:opacity-40"
                    >
                      {showBankLink ? <ChevronUp size={14} /> : <Plus size={14} />}
                      {showBankLink ? "Close bank connection form" : "Change or add a bank account"}
                    </button>
                  )}

                  {showBankLink && hostedPlaidEnabled && !accountRestricted && accountVerified && (locationApproved || availableBalance > 0) && (
                    <SeamlessPlaidBankLink
                      legalName={state?.legal_name || ""}
                      hasWithdrawableBalance={availableBalance > 0}
                      disabled={effectiveWithdrawalHold || !accountVerified || (!locationApproved && availableBalance <= 0)}
                      onComplete={async () => {
                        setShowBankLink(false);
                        await load();
                      }}
                    />
                  )}
                </div>
              )}
            </div>

            <div className="space-y-3">
              <label htmlFor="wallet-transfer-amount" className="block text-xs font-medium text-white/60">
                {direction === "deposit" ? "Amount to add to wallet" : "Amount"}
              </label>
              <div className="flex h-16 items-center rounded-2xl border border-white/10 bg-black/25 px-4 focus-within:border-[#C9A84C]/60">
                <span className="text-2xl font-semibold text-white/35">$</span>
                <input
                  id="wallet-transfer-amount"
                  type="number"
                  inputMode="decimal"
                  min="0"
                  max={direction === "deposit" ? 1093.8 : Math.min(1100, availableBalance)}
                  step="0.01"
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                  placeholder="0.00"
                  disabled={ineligible || !bankReadyForDirection || !transferDirectionEnabled}
                  className="h-full min-w-0 flex-1 bg-transparent px-2 text-2xl font-bold text-white outline-none placeholder:text-white/15 disabled:opacity-40"
                />
                <span className="text-xs font-medium text-white/30">USD</span>
              </div>

              {direction === "deposit" && (
                <>
                  <div className="grid grid-cols-4 gap-2" aria-label="Quick deposit amounts">
                    {[10, 25, 50, 100].map((value) => (
                      <button
                        key={value}
                        type="button"
                        aria-pressed={parsedAmount === value}
                        onClick={() => setAmount(String(value))}
                        disabled={ineligible || !depositSourceReady || !depositsEnabled || !!busy}
                        className={
                          "rounded-xl border px-2 py-2.5 text-sm font-semibold transition-colors disabled:opacity-30 " +
                          (parsedAmount === value
                            ? "border-[#C9A84C]/60 bg-[#C9A84C]/10 text-[#E7C866]"
                            : "border-white/10 bg-white/[0.025] text-white/60 hover:border-white/20 hover:text-white")
                        }
                      >
                        ${value}
                      </button>
                    ))}
                  </div>
                  <p className="text-center text-[11px] text-white/30">
                    ${MIN_DEPOSIT_AMOUNT.toFixed(2)} minimum deposit
                  </p>
                </>
              )}

              {direction === "withdrawal" && availableBalance > 0 && (
                <button
                  type="button"
                  onClick={() => setAmount(String(Math.min(1100, availableBalance).toFixed(2)))}
                  disabled={ineligible || !withdrawalsEnabled || !!busy}
                  className="w-full text-center text-xs font-medium text-[#C9A84C] hover:underline disabled:opacity-40"
                >
                  {availableBalance > 1100 ? "Withdraw $1,100.00 — no fee" : `Withdraw available funds ($${availableBalance.toFixed(2)}) — no fee`}
                </button>
              )}

              {direction === "withdrawal" && (
                <p role="note" className="text-center text-xs leading-relaxed text-white/60">
                  Up to $1,100 per request. Bank transfers share a platform allowance of $1,100 over 24 hours and $22,000 over 31 days. If capacity is full, your funds stay in your wallet so you can try again later. Requests are not queued automatically. Bank processing time is additional.
                </p>
              )}

              {exceedsWithdrawalLimit && <p role="alert" className="text-center text-xs text-red-400">Enter $1,100.00 or less. Remaining funds stay in your wallet.</p>}

              {exceedsAvailableBalance && (
                <p className="text-center text-xs text-red-400">
                  Enter an amount no greater than your ${availableBalance.toFixed(2)} available-to-withdraw balance.
                </p>
              )}

              {direction === "withdrawal" && parsedAmount > 0 && parsedAmount < SMALL_WITHDRAWAL_THRESHOLD && !exceedsAvailableBalance && (
                isFullBalanceWithdrawal ? (
                  <div className="rounded-xl border border-emerald-500/20 bg-emerald-500/[0.06] px-3 py-2.5 text-center">
                    <p className="text-xs font-medium text-emerald-300">No fee — you're withdrawing your full balance</p>
                  </div>
                ) : (
                  <div className="rounded-xl border border-amber-500/20 bg-amber-500/[0.06] px-3 py-2.5 text-center">
                    <p className="text-xs font-semibold text-amber-300">
                      ${SMALL_WITHDRAWAL_FEE.toFixed(2)} fee applies below ${SMALL_WITHDRAWAL_THRESHOLD.toFixed(2)}
                    </p>
                    <p className="mt-1 text-[11px] text-amber-200/70">
                      ${(parsedAmount + SMALL_WITHDRAWAL_FEE).toFixed(2)} will leave your wallet to send ${parsedAmount.toFixed(2)}.
                    </p>
                  </div>
                )
              )}

              {direction === "deposit" && quote && (
                <div aria-label="Deposit breakdown" aria-live="polite" className="rounded-2xl border border-white/10 bg-black/20 p-4 text-sm space-y-2">
                  <div className="flex justify-between gap-3 text-white/75"><span>Added to your wallet</span><span>${quote.walletAmount.toFixed(2)}</span></div>
                  <div className="flex justify-between gap-3 text-white/60"><span>Deposit fee</span><span>${quote.fee.toFixed(2)}</span></div>
                  <div className="flex justify-between gap-3 border-t border-white/10 pt-3 font-semibold text-white"><span>Total bank charge</span><span>${quote.bankDebit.toFixed(2)}</span></div>
                  <p className="pt-1 text-[11px] leading-relaxed text-white/45">The deposit fee helps ChessBet cover payment processing and verification expenses. Your wallet receives the full ${quote.walletAmount.toFixed(2)} after Seamless confirms the deposit and clearing is complete.</p>
                  <p className="text-[11px] leading-relaxed text-white/60">By clicking Deposit, you authorize a one-time debit of ${quote.bankDebit.toFixed(2)} from the connected bank shown above, including the ${quote.fee.toFixed(2)} deposit fee.</p>
                </div>
              )}

              {direction === "deposit" && (
                <p className="text-center text-xs leading-relaxed text-white/50">
                  Deposits typically appear in your ChessBet wallet within 3–4 business days.
                  We’ll notify you when your funds land.
                </p>
              )}

              <Button
                onClick={submit}
                disabled={!canSubmit}
                className="w-full rounded-2xl gold-gradient py-3.5 text-sm font-bold text-black hover:opacity-90 disabled:opacity-30"
              >
                {transferBusy ? (
                  <><Loader2 size={16} className="mr-2 animate-spin" /> Processing securely...</>
                ) : notVerified ? (["pending", "review_required"].includes(state?.identity?.status) ? "Awaiting identity approval" : state?.identity?.status === "rejected" ? "Verification not approved" : "Verify your identity first") : direction === "deposit" ? (
                  !depositsEnabled
                    ? (!locationApproved ? "Verify your location first" : "Deposits are temporarily unavailable")
                    : !depositSourceReady
                      ? "Choose a connected bank"
                    : parsedAmount > 1093.8
                      ? "Maximum deposit is $1,093.80 plus fee"
                    : amount && !/^\d+(?:\.\d{1,2})?$/.test(amount)
                      ? "Enter an amount with up to 2 decimals"
                    : !formattedAmount
                      ? "Enter an amount"
                      : !meetsMinimum
                        ? "Minimum deposit is $" + MIN_DEPOSIT_AMOUNT.toFixed(2)
                        : "Deposit $" + (quote?.bankDebit.toFixed(2) || "")
                ) : (
                  !withdrawalsEnabled
                    ? "Withdrawals are temporarily unavailable"
                    : !formattedAmount
                      ? "Enter an amount"
                      : exceedsWithdrawalLimit
                        ? "Maximum withdrawal is $1,100.00"
                      : exceedsAvailableBalance
                        ? "Amount exceeds available balance"
                        : "Withdraw $" + formattedAmount + " to bank"
                )}
              </Button>

              <p className="text-center text-[11px] leading-relaxed text-white/25">
                Secure bank transfer via Seamless. Your bank login is never shared with ChessBet.
              </p>
            </div>
          </div>
        </div>
      )}

      {notice && <p role="status" className="text-center text-sm text-[#C9A84C]">{notice}</p>}
      {error && (
        <p role="alert" className="flex items-center justify-center gap-1.5 text-center text-xs text-red-400">
          <AlertTriangle size={13} /> {error}
        </p>
      )}

      <AlertDialog
        open={!!bankToDisconnect}
        onOpenChange={(open) => !open && setBankToDisconnect(null)}
      >
        <AlertDialogContent className="border-white/10 bg-[#151515] text-white">
          <AlertDialogHeader>
            <AlertDialogTitle>Disconnect this bank account?</AlertDialogTitle>
            <AlertDialogDescription className="text-white/55">
              ChessBet will remove the account from Seamless and revoke its ACH authorization.
              You can reconnect this bank or add a different bank later. A bank with a transfer
              in progress cannot be disconnected.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="border-white/10 bg-transparent text-white hover:bg-white/5">
              Keep connected
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => bankToDisconnect && manageBank("disconnect", bankToDisconnect)}
              className="bg-red-600 text-white hover:bg-red-500"
            >
              Disconnect bank
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

    </div>
  );
}

