import React, { useState } from "react";
import {
  ArrowUpRight,
  ArrowDownLeft,
  Plus,
  Minus,
  ChevronDown,
  Copy,
  Check,
} from "lucide-react";
import moment from "moment";
import TransactionPagination from "@/components/wallet/TransactionPagination";
import ReportContestButton from "@/components/disputes/ReportContestButton";
import { getTransferFailureMessage } from "@/components/wallet/transferFailureCopy";

const typeConfig = {
  deposit: { icon: ArrowDownLeft, color: "text-green-400", bg: "bg-green-500/10", label: "Deposit" },
  withdrawal: { icon: ArrowUpRight, color: "text-red-400", bg: "bg-red-500/10", label: "Withdraw Funds" },
  wager_lock: { icon: Minus, color: "text-orange-400", bg: "bg-orange-500/10", label: "Contest Entry Reserved" },
  wager_refund: { icon: Plus, color: "text-blue-400", bg: "bg-blue-500/10", label: "Contest Entry Refund" },
  payout: { icon: ArrowDownLeft, color: "text-[#C9A84C]", bg: "bg-[#C9A84C]/10", label: "Contest Winnings" },
  wager_forfeit: { icon: Minus, color: "text-red-400", bg: "bg-red-500/10", label: "Contest Entry Forfeited" },
  service_fee_charge: { icon: Minus, color: "text-orange-400", bg: "bg-orange-500/10", label: "Platform Service Fee" },
  service_fee_refund: { icon: Plus, color: "text-blue-400", bg: "bg-blue-500/10", label: "Platform Service Fee Refund" },
  withdrawal_fee: { icon: Minus, color: "text-amber-400", bg: "bg-amber-500/10", label: "Small Withdrawal Fee" },
  withdrawal_fee_refund: { icon: Plus, color: "text-blue-400", bg: "bg-blue-500/10", label: "Withdrawal Fee Refund" },
};

const SMALL_WITHDRAWAL_THRESHOLD = 10;

const statusConfig = {
  reversed: { label: "Reversed", className: "text-red-300 bg-red-500/10 border-red-500/20" },
  completed: { label: "Completed", className: "text-green-400 bg-green-500/10 border-green-500/20" },
  pending: { label: "Pending", className: "text-[#C9A84C] bg-[#C9A84C]/10 border-[#C9A84C]/20" },
  failed: { label: "Not applied", className: "text-white/45 bg-white/5 border-white/10" },
  failed_transfer: { label: "Failed", className: "text-red-300 bg-red-500/10 border-red-500/20" },
  review_required: { label: "Review required", className: "text-orange-300 bg-orange-500/10 border-orange-500/20" },
  pending_release: { label: "Pending release", className: "text-[#C9A84C] bg-[#C9A84C]/10 border-[#C9A84C]/20" },
  clearing: { label: "Clearing", className: "text-[#C9A84C] bg-[#C9A84C]/10 border-[#C9A84C]/20" },
};

const incomingTypes = ["deposit", "payout", "wager_refund", "service_fee_refund", "withdrawal_fee_refund"];
const REPORT_WINDOW_MS = 24 * 60 * 60 * 1000;

function shortReference(id) {
  if (!id) return null;
  return id.slice(-8).toUpperCase();
}

function formatMoney(value) {
  return Number(value || 0).toFixed(2);
}

function titleCase(value) {
  if (!value) return null;
  return value.replace(/_/g, " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function serverTimestampMs(value) {
  if (!value) return NaN;
  const text = String(value);
  const normalized = /Z$|[+-]\d{2}:?\d{2}$/.test(text) ? text : `${text}Z`;
  return new Date(normalized).getTime();
}

function isSuppressedDuplicate(tx) {
  if (tx.status !== "failed") return false;
  const details = String(tx.description || "").toLowerCase();
  return (
    details.includes("duplicate") ||
    details.includes("another settlement") ||
    details.includes("already completed") ||
    details.includes("already processed")
  );
}

function getTransactionExplanation(tx, match) {
  const amount = `$${formatMoney(tx.amount)}`;
  const entry = match?.wager_amount != null ? `$${formatMoney(match.wager_amount)}` : null;

  if (tx.type === "deposit" && tx.status === "reversed") {
    return { heading: "Deposit returned", text: "The bank returned this deposit. Its wallet credit has been reversed. Any amount that could not be recovered is subject to account review." };
  }
  if (tx.type === "deposit" && !["failed", "reversed"].includes(tx.status) &&
      ["awaiting_evidence", "mismatch"].includes(tx.deposit_reconciliation_status)) {
    return { heading: "Verifying deposit", text: "We are checking the bank charge, processor fee, and amount received with Seamless. This deposit is unavailable until verification and clearing are complete." };
  }
  if (tx.type === "deposit" && tx.deposit_hold_status === "held") {
    return { heading: "Clearing", text: `${amount} is awaiting the final provider and settlement checks before it becomes available to play. A separate withdrawal hold applies.` };
  }
  if (tx.type === "deposit" && tx.deposit_hold_status === "released" && tx.deposit_withdrawal_status === "held") {
    const review = tx.deposit_release_at ? moment(tx.deposit_release_at).format("MMM D, YYYY [at] h:mm A") : "the displayed withdrawal review date";
    return { heading: "Available to play", text: `${amount} was made available for contest play. Withdrawal review is on or after ${review}, five business days from submission, and requires a successful final bank check. Prizes and refunds funded by this deposit inherit the remaining withdrawal hold. Later bank returns remain possible.` };
  }
  if (tx.type === "payout" && tx.payout_hold_status === "held") {
    const releaseText = tx.payout_release_at
      ? `eligible for release on or after ${moment(tx.payout_release_at).format("MMM D [at] h:mm A")} when no open dispute or blocking integrity or reconciliation flag remains`
      : "eligible for release after the 24-hour reporting window when no open dispute or blocking integrity or reconciliation flag remains";
    return {
      heading: "Pending release",
      text: `You won this contest and ${amount} has been credited, but held pending the standard 24-hour contest reporting window — ${releaseText}. It does not count toward your available balance yet. Any inherited deposit withdrawal hold still applies after release.`,
    };
  }
  if (isSuppressedDuplicate(tx)) {
    return {
      heading: "No balance change",
      text: "This was a duplicate processing attempt. It did not change your balance and can be ignored because the contest was completed in another transaction.",
    };
  }
  if (tx.status === "failed" && ["deposit", "withdrawal"].includes(tx.type)) {
    return {
      heading: "Why it failed",
      text: tx.type === "deposit"
        ? `${getTransferFailureMessage(tx)} No money was added to your ChessBet wallet.`
        : `${getTransferFailureMessage(tx)} The withdrawal was not sent and any reserved funds were returned to your available balance.`,
    };
  }
  if (tx.status === "failed") {
    return {
      heading: "Not applied",
      text: "This transaction did not change your balance. Check the other transactions for this contest; if the expected result is missing, report the contest within 24 hours.",
    };
  }
  if (tx.status === "review_required") {
    return {
      heading: "Review required",
      text: "Processing paused for review, so the referenced amount is not shown as completed. ChessBet will review the contest and its ledger records.",
    };
  }
  if (tx.status === "pending") {
    return {
      heading: "Still processing",
      text: "This transaction has not finished processing. Your balance and transaction history will update when it completes.",
    };
  }

  const explanations = {
    deposit: `This transaction added ${amount} to your available balance.`,
    withdrawal: `This transaction removed ${amount} from your ChessBet balance for withdrawal.`,
    wager_lock: `Your ${amount} contest entry moved from available funds to reserved funds when the contest began.`,
    wager_refund: `Your ${amount} contest entry was returned to your available balance.`,
    wager_forfeit: `You lost this contest, so your ${amount} reserved contest entry was forfeited to your opponent and is no longer part of your balance.`,
    payout: entry
      ? `You won this contest and ${amount} was added to your available balance. The prize is funded by both players’ ${entry} contest entries; platform service fees are separate.`
      : `You won this contest and ${amount} was added to your available balance. Platform service fees are separate from the prize.`,
    service_fee_charge: `The separate ${amount} platform service fee was reserved when the contest began. It is not deducted from the winner’s prize.`,
    service_fee_refund: `The ${amount} platform service fee was returned to your available balance.`,
    withdrawal_fee: `A ${amount} fee applies to withdrawals under $${SMALL_WITHDRAWAL_THRESHOLD} to help cover bank transfer costs. Withdrawing your full available balance at once waives this fee.`,
    withdrawal_fee_refund: `${amount} was returned to your available balance because the related bank withdrawal did not complete.`,
  };

  return {
    heading: "What this means",
    text: explanations[tx.type] || tx.description || "This completed transaction has been reflected in your balance.",
  };
}

function getMatchResult(match, userId) {
  if (!match) return null;
  if (match.status === "cancelled" || match.result === "cancelled") return "Cancelled";
  if (match.status === "disputed") return "Under review";
  if (match.status !== "completed") return titleCase(match.status);
  if (match.result === "draw" || !match.winner_id) return "Draw";
  return match.winner_id === userId ? "Won" : "Lost";
}

function DetailItem({ label, value }) {
  if (value == null || value === "") return null;
  return (
    <div>
      <p className="text-[10px] uppercase tracking-wider text-white/25">{label}</p>
      <p className="mt-1 text-xs font-medium text-white/70">{value}</p>
    </div>
  );
}

export default function TransactionHistory({
  transactions,
  matchDetailsById = {},
  userId,
  page,
  pageSize,
  totalCount,
  onPageChange,
}) {
  const [expandedId, setExpandedId] = useState(null);
  const [copiedId, setCopiedId] = useState(null);
  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize));
  const rangeStart = totalCount === 0 ? 0 : (page - 1) * pageSize + 1;
  const rangeEnd = Math.min(page * pageSize, totalCount);

  const copyReference = async (transactionId) => {
    try {
      await navigator.clipboard.writeText(transactionId);
      setCopiedId(transactionId);
      window.setTimeout(() => setCopiedId(null), 1800);
    } catch {
      setCopiedId(null);
    }
  };

  if (totalCount === 0) {
    return (
      <div className="text-center py-10 rounded-2xl bg-white/[0.02] border border-white/5">
        <p className="text-white/30 text-sm">No transactions yet</p>
      </div>
    );
  }

  return (
    <div>
      <p className="text-xs text-white/30 mb-3">
        Showing {rangeStart}–{rangeEnd} of {totalCount} transactions
      </p>
      <div className="space-y-2">
        {transactions.map((tx) => {
          const config = typeConfig[tx.type] || typeConfig.deposit;
          const Icon = config.icon;
          const isIncoming = incomingTypes.includes(tx.type);
          const isExpanded = expandedId === tx.id;
          const context = tx.match_id ? matchDetailsById[tx.match_id] : null;
          const match = context?.match;
          const matchReference = shortReference(tx.match_id);
          const transactionReference = shortReference(tx.id);
          const opponentName = context?.opponentName;
          const timeControl = match?.display_name || titleCase(match?.time_control);
          const result = getMatchResult(match, userId);
          const isDepositReview = tx.type === "deposit" && !["failed", "reversed"].includes(tx.status) &&
            ["awaiting_evidence", "mismatch"].includes(tx.deposit_reconciliation_status);
          const isReversed = tx.status === "reversed";
          const isDepositClearing = tx.type === "deposit" && tx.deposit_hold_status === "held";
          const isPendingRelease = (tx.type === "payout" && tx.payout_hold_status === "held") || isDepositClearing;
          const isFailed = tx.status === "failed";
          const isFailedTransfer = isFailed && ["deposit", "withdrawal"].includes(tx.type);
          const failureMessage = isFailedTransfer ? getTransferFailureMessage(tx) : "";
          const status = isDepositReview ? statusConfig.review_required : isReversed ? statusConfig.reversed : isDepositClearing
            ? statusConfig.clearing
            : isPendingRelease
              ? statusConfig.pending_release
            : isFailedTransfer
              ? statusConfig.failed_transfer
              : (statusConfig[tx.status] || statusConfig.completed);
          const needsReview = tx.status === "review_required" || isDepositReview;
          const explanation = getTransactionExplanation(tx, match);
          const transactionCreatedMs = serverTimestampMs(tx.created_date);
          const transactionAgeMs = Date.now() - transactionCreatedMs;
          const hasReportableContest = Boolean(tx.match_id && match);
          const canReportContest =
            hasReportableContest &&
            Number.isFinite(transactionAgeMs) &&
            transactionAgeMs >= -5 * 60 * 1000 &&
            transactionAgeMs <= REPORT_WINDOW_MS;
          const reportDeadline = Number.isFinite(transactionCreatedMs)
            ? transactionCreatedMs + REPORT_WINDOW_MS
            : null;
          const amountLabel = isReversed ? `Reversed · $${formatMoney(tx.amount)}` : isFailed
            ? `Not applied · $${formatMoney(tx.amount)}`
            : needsReview
              ? `Review · $${formatMoney(tx.amount)}`
              : isPendingRelease
                ? `Pending · +$${formatMoney(tx.amount)}`
                : `${isIncoming ? "+" : "-"}$${formatMoney(tx.amount)}`;
          const amountClass = isFailed || needsReview || isReversed
            ? "text-white/45"
            : isPendingRelease
              ? "text-[#C9A84C]"
              : isIncoming
                ? "text-green-400"
                : "text-red-400";
          const subtitleParts = match
            ? [
                opponentName ? `vs. ${opponentName}` : "Contest transaction",
                timeControl,
                matchReference ? `Match ${matchReference}` : null,
              ]
            : isFailedTransfer
              ? [failureMessage]
              : [moment(tx.created_date).format("MMM D, YYYY"), titleCase(tx.status || "completed")];

          return (
            <div
              key={tx.id}
              className={`overflow-hidden rounded-2xl border transition-colors ${
                isExpanded
                  ? "bg-white/[0.045] border-white/10"
                  : "bg-white/[0.03] border-white/5"
              }`}
            >
              <button
                type="button"
                onClick={() => setExpandedId(isExpanded ? null : tx.id)}
                aria-expanded={isExpanded}
                className="w-full p-4 flex items-center justify-between gap-3 text-left hover:bg-white/[0.025] transition-colors"
              >
                <div className="flex min-w-0 items-center gap-3">
                  <div className={`w-9 h-9 rounded-xl shrink-0 flex items-center justify-center ${config.bg}`}>
                    <Icon size={16} className={config.color} />
                  </div>
                  <div className="min-w-0">
                    <p className="text-sm font-semibold text-white">{config.label}</p>
                    <p className="mt-0.5 truncate text-[11px] text-white/35">
                      {subtitleParts.filter(Boolean).join(" · ")}
                    </p>
                  </div>
                </div>
                <div className="flex shrink-0 items-center gap-2.5">
                  <div className="text-right">
                    <p className={`text-sm font-bold ${amountClass}`}>
                      {amountLabel}
                    </p>
                    <p className="mt-0.5 text-[10px] text-white/25">
                      {moment(tx.created_date).format("h:mm A")}
                    </p>
                  </div>
                  <ChevronDown
                    size={15}
                    className={`text-white/25 transition-transform ${isExpanded ? "rotate-180" : ""}`}
                  />
                </div>
              </button>

              {isExpanded && (
                <div className="border-t border-white/[0.06] px-4 pb-4 pt-3">
                  <div className="mb-4 flex flex-wrap items-center justify-between gap-2">
                    <span className={`rounded-full border px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider ${status.className}`}>
                      {status.label}
                    </span>
                    <p className="text-[11px] text-white/30">
                      {moment(tx.created_date).format("MMM D, YYYY [at] h:mm:ss A")}
                    </p>
                  </div>

                  <div className="grid grid-cols-2 gap-x-4 gap-y-4 sm:grid-cols-3">
                    <DetailItem
                      label={tx.status === "completed" ? "Transaction amount" : "Referenced amount"}
                      value={amountLabel}
                    />
                    {tx.type === "deposit" && tx.deposit_pricing_version && (
                      <>
                        <DetailItem label="Deposit fee" value={`$${formatMoney(tx.deposit_processing_fee)}`} />
                        <DetailItem label="Authorized bank charge" value={`$${formatMoney(tx.deposit_bank_debit)}`} />
                      </>
                    )}
                    {match && (
                      <>
                        <DetailItem label="Opponent" value={opponentName || "Opponent"} />
                        <DetailItem label="Time control" value={timeControl} />
                        <DetailItem label="Contest result" value={result} />
                        <DetailItem label="Entry amount" value={`$${formatMoney(match.wager_amount)}`} />
                        <DetailItem label="Platform service fee" value={`$${formatMoney(match.platform_service_fee)}`} />
                        <DetailItem
                          label="Total reserved per player"
                          value={`$${formatMoney((match.wager_amount || 0) + (match.platform_service_fee || 0))}`}
                        />
                      </>
                    )}
                  </div>

                  <div className="mt-4 rounded-xl border border-white/[0.06] bg-white/[0.025] px-3 py-2.5">
                    <p className="text-[10px] uppercase tracking-wider text-white/25">{explanation.heading}</p>
                    <p className="mt-1 text-xs leading-relaxed text-white/60">{explanation.text}</p>
                  </div>

                  {hasReportableContest && (
                    <div className="mt-3 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/[0.06] px-3 py-2.5">
                      <div>
                        <p className="text-xs font-medium text-white/65">Concern about this contest?</p>
                        <p className="mt-0.5 text-[11px] text-white/30">
                          {canReportContest
                            ? `Reports from wallet history are available until ${moment(reportDeadline).format("MMM D [at] h:mm A")}.`
                            : "The 24-hour reporting window for this transaction has closed."}
                        </p>
                      </div>
                      {canReportContest && (
                        <ReportContestButton
                          matchId={tx.match_id}
                          gameId={match?.game_id}
                          transactionId={tx.id}
                          label="Report this contest"
                          className="rounded-lg border border-white/10 px-3 py-2 font-semibold !text-white/60 hover:bg-white/5 hover:!text-white/85"
                        />
                      )}
                    </div>
                  )}

                  <div className="mt-4 flex items-center justify-between gap-3 border-t border-white/[0.05] pt-3">
                    <div className="min-w-0">
                      <p className="text-[10px] uppercase tracking-wider text-white/25">Transaction reference</p>
                      <p className="mt-1 font-mono text-[11px] text-white/45">{transactionReference}</p>
                    </div>
                    <button
                      type="button"
                      onClick={() => copyReference(tx.id)}
                      className="inline-flex items-center gap-1.5 rounded-lg border border-white/10 px-2.5 py-1.5 text-[11px] font-semibold text-white/55 hover:bg-white/5 hover:text-white/80"
                    >
                      {copiedId === tx.id ? <Check size={12} /> : <Copy size={12} />}
                      {copiedId === tx.id ? "Copied" : "Copy ID"}
                    </button>
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
      {totalPages > 1 && (
        <TransactionPagination page={page} totalPages={totalPages} onPageChange={onPageChange} />
      )}
    </div>
  );
}

src/components/wallet/DepositReconciliat:
import React, { useEffect, useState } from 'react';
import { base44 } from '@/api/base44Client';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';

const usd = value => '$' + Number(value || 0).toFixed(2);
export default function DepositReconciliationPanel() {
  const [rows, setRows] = useState([]);
  const [selected, setSelected] = useState('');
  const [kind, setKind] = useState('settlement');
  const [values, setValues] = useState({});
  const [confirmed, setConfirmed] = useState(false);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(false);
  const tx = rows.find(row => row.id === selected);
  const load = async (skip = page * 100) => {
    try {
      const res = await base44.functions.invoke('reconcileDepositSettlement', { action: 'list', skip });
      setRows(res.data?.transactions || []);
      setHasMore(Boolean(res.data?.hasMore));
    } catch {
      setMessage('Could not load deposit reconciliation. Please refresh.');
    }
  };
  useEffect(() => { load(page * 100); }, [page]);
  const reset = () => { setValues({}); setConfirmed(false); setMessage(''); };
  const fields = kind === 'settlement'
    ? [['bankDebit', 'Actual bank charge'], ['processingFee', 'Actual Seamless processing fee'], ['netReceived', 'Actual net received by ChessBet']]
    : [['processingFeeRetained', 'Processing fee retained after return'], ['returnFee', 'Additional Seamless return charge'], ['additionalCashDebit', 'Total processor costs after return, excluding wallet principal']];
  const submit = async event => {
    event.preventDefault();
    setBusy(true); setMessage('');
    try {
      const res = await base44.functions.invoke('reconcileDepositSettlement', {
        action: kind === 'settlement' ? 'recordSettlement' : 'recordReturn',
        transactionId: selected, ...values, confirmedAgainstSeamless: confirmed,
      });
      setMessage(res.data?.message || 'Reconciliation saved.');
      await load();
      setConfirmed(false);
    } catch (error) {
      setMessage(error?.response?.data?.error || error?.data?.error || 'Verification did not complete. Check the evidence and try again.');
    } finally { setBusy(false); }
  };
  return (
    <section className="mt-8 rounded-2xl border border-white/10 bg-white/[0.03] p-5 text-white">
      <h2 className="text-lg font-semibold">Deposit reconciliation</h2>
      <p className="mt-2 text-sm text-white/60">
        Verify new deposits against a Seamless settlement statement or written support confirmation.
        A payment marked Processed is also checked before wallet credit and release.
        A transaction-level fee of $0.00 is not proof that Seamless charged no processing fee.
      </p>
      <div className="mt-4 flex gap-2 items-center">
        <Button type="button" variant="outline" disabled={busy} onClick={() => load()}>Refresh deposits</Button>
        <Button type="button" variant="outline" disabled={busy || page === 0} onClick={() => { reset(); setSelected(''); setPage(page - 1); }}>Previous</Button>
        <Button type="button" variant="outline" disabled={busy || !hasMore} onClick={() => { reset(); setSelected(''); setPage(page + 1); }}>Next</Button>
      </div>
      {rows.length === 0 ? <p className="mt-4 text-sm text-white/50">No deposits using the fee feature on this page.</p> : (
        <form className="mt-4 space-y-4" onSubmit={submit}>
          <label className="block text-sm">Deposit
            <select className="mt-1 w-full rounded border border-white/20 bg-[#151515] p-2"
              value={selected} disabled={busy} required onChange={event => { setSelected(event.target.value); reset(); }}>
              <option value="">Select a deposit</option>
              {rows.map(row => <option key={row.id} value={row.id}>
                {usd(row.amount)} · {row.created_date?.slice(0, 10)} · {row.status} · {row.reconciliation_status} · {row.id}
              </option>)}
            </select>
          </label>
          {tx && <>
            <div className="rounded-lg bg-black/20 p-3 text-sm space-y-1">
              <p>Seamless payment ID: <span className="break-all">{tx.provider_reference_id || 'Awaiting provider reference'}</span></p>
              <p>Authorized: bank charge {usd(tx.bank_debit)} · customer deposit fee {usd(tx.processing_fee)} · wallet credit {usd(tx.amount)}</p>
              <p>Settlement: {tx.reconciliation_status.replaceAll('_', ' ')} · Return fees: {(tx.return_reconciliation_status || 'not reviewed').replaceAll('_', ' ')}</p>
              {tx.reconciliation_reason && <p className="text-amber-300">Review reason: {tx.reconciliation_reason.replaceAll('_', ' ')}</p>}
            </div>
            <label className="block text-sm">Review
              <select className="mt-1 w-full rounded border border-white/20 bg-[#151515] p-2" value={kind}
                disabled={busy} onChange={event => { setKind(event.target.value); reset(); }}>
                <option value="settlement">Settlement amounts</option>
                <option value="return">Returned or failed deposit — processor costs</option>
              </select>
            </label>
            {kind === 'return' && <p className="text-sm text-white/60">
              Record the actual unrecovered processor costs across this deposit and its return.
              Wallet principal is reversed separately. These entries do not charge the player again.
            </p>}
            <div className="grid gap-3 sm:grid-cols-3">
              {fields.map(([key, label]) => <label key={key} className="block text-sm">{label} (USD)
                <Input className="mt-1 bg-black/20 text-white" type="number" min="0" step="0.01"
                  required disabled={busy} value={values[key] || ''}
                  onChange={event => setValues({ ...values, [key]: event.target.value })} />
              </label>)}
            </div>
            <label className="block text-sm">Evidence source
              <select className="mt-1 w-full rounded border border-white/20 bg-[#151515] p-2" required
                value={values.source || ''} disabled={busy} onChange={event => setValues({ ...values, source: event.target.value })}>
                <option value="">Select source</option>
                <option value="seamless_statement">Seamless settlement statement</option>
                <option value="seamless_support">Written Seamless support confirmation</option>
              </select>
            </label>
            <label className="block text-sm">Statement reference and line/date, or support case reference
              <Input className="mt-1 bg-black/20 text-white" required minLength={8} maxLength={1000}
                disabled={busy} value={values.evidenceReference || ''}
                onChange={event => setValues({ ...values, evidenceReference: event.target.value })} />
            </label>
            <label className="flex gap-2 items-start text-sm text-white/70">
              <input type="checkbox" required disabled={busy} checked={confirmed} onChange={event => setConfirmed(event.target.checked)} className="mt-1" />
              I checked these actual amounts against the referenced Seamless evidence for this payment.
            </label>
            <Button type="submit" disabled={busy || !confirmed}>{busy ? 'Verifying…' : 'Verify and record evidence'}</Button>
            <p className="text-xs text-white/50">An exact settlement match makes the requested wallet amount eligible for play after provider verification. A separate withdrawal hold and final bank-status check still apply.</p>
          </>}
        </form>
      )}
      {message && <p className="mt-4 text-sm text-amber-200" role="status">{message}</p>}
    </section>
  );
}
